def choose_move(observation):
    def clamp(v):
        return -1 if v < -1 else 1 if v > 1 else v

    def as_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        if isinstance(v, dict):
            x = v.get("x", v.get("col", v.get("y", 0)))
            y = v.get("y", v.get("row", v.get("x", 0)))
            return x, y
        return None

    def first_pos(obj):
        if obj is None:
            return None
        p = as_pair(obj)
        if p is not None:
            return p
        if isinstance(obj, dict):
            for k in ("position", "pos", "loc", "location", "self", "agent"):
                p = first_pos(obj.get(k))
                if p is not None:
                    return p
            for v in obj.values():
                p = first_pos(v)
                if p is not None:
                    return p
        if isinstance(obj, (list, tuple)):
            for item in obj:
                p = first_pos(item)
                if p is not None:
                    return p
        return None

    def collect_positions(obj):
        out = []
        if obj is None:
            return out
        p = as_pair(obj)
        if p is not None:
            out.append(p)
            return out
        if isinstance(obj, dict):
            for v in obj.values():
                out.extend(collect_positions(v))
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                out.extend(collect_positions(item))
        return out

    pos = first_pos(
        observation.get("position")
        or observation.get("pos")
        or observation.get("self")
        or observation.get("agent")
        or observation.get("agent_position")
    )
    if pos is None:
        pos = (0, 0)
    x, y = pos

    resources = []
    for key in ("resources", "resource_positions", "resource", "items", "food", "pickups"):
        resources.extend(collect_positions(observation.get(key)))
    targets = []
    for key in ("targets", "goal", "goals", "objective", "objectives", "capture_points", "bases"):
        targets.extend(collect_positions(observation.get(key)))
    enemies = []
