    # infer nearby points from grid-like observations if explicit lists are absent
    grid = observation.get("grid")
    if not resources and not targets and isinstance(grid, (list, tuple)):
        for j, row in enumerate(grid):
            if isinstance(row, (list, tuple)):
                for i, cell in enumerate(row):
                    if cell in (1, 2, 3, 4, 5, "R", "r", "G", "g", "T", "t"):
                        targets.append((i, j))

    moves = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = x + dx, y + dy
            score = 0

            # attraction to nearest useful object
            best_res = None
            for rx, ry in resources:
                d = abs(rx - nx) + abs(ry - ny)
                if best_res is None or d < best_res:
                    best_res = d
            best_tgt = None
            for tx, ty in targets:
                d = abs(tx - nx) + abs(ty - ny)
                if best_tgt is None or d < best_tgt:
                    best_tgt = d

            if best_res is not None:
                score += 12 - best_res * 2
            if best_tgt is not None:
                score += 8 - best_tgt * 2

            # enemy avoidance / pursuit balance
            nearest_enemy = None
            for ex, ey in enemies:
                d = abs(ex - nx) + abs(ey - ny)
                if nearest_enemy is None or d < nearest_enemy:
                    nearest_enemy = d
            if nearest_enemy is not None:
                if nearest_enemy == 0:
                    score -= 10
                else:
                    score += min(nearest_enemy, 6)

            # prefer staying put only when nothing is known
            if dx == 0 and dy == 0:
                score -= 1

            # slight bias toward diagonal movement when chasing known targets
            if (resources or targets) and dx != 0 and dy != 0:
                score += 1

            moves.append((score, dx, dy))

    moves.sort(key=lambda t: (-t[0], abs(t[1]) + abs(t[2]), t[1], t[2]))
    _, dx, dy = moves[0]
    return [clamp(dx), clamp(dy)]

